const taskActions=new Set(['localImport','analyze','generateReply','testModel','ocrTest','sendPreview','backup','restore','recordsImport','folderImport','mediaImport','nativeMedia','export']);
function busy(){return submitting||fileBusy||pendingJobs.size>0||!!state?.jobs?.some(j=>j.state==='running')}
