const pages=[['home','◈','总览'],['sources','⇄','数据接入'],['records','☷','聊天记录'],['media','▧','媒体资料'],['insights','✧','AI 工具箱'],['statistics','▥','聊天统计'],['persona','◎','个人分身'],['reply','↗','回复试验室'],['automation','⌁','微信自动回复'],['backups','◷','备份与恢复'],['settings','⚙','模型与设置']];
