async function api(path,data){let r;try{r=await fetch(path,{method:data===undefined?'GET':'POST',headers:{'X-Studio-Token':token,...(data===undefined?{}:{'Content-Type':'application/json'})},body:data===undefined?undefined:JSON.stringify(data)})}catch{throw requestError('无法连接本机工作台，请检查程序是否仍在运行','network')}let v;try{v=await r.json()}catch{throw requestError('本机服务返回了无法读取的响应，请重试或重新打开工作台','service',r.status)}if(!r.ok)throw requestError(v?.error||'操作未完成','service',r.status);return v}
function unavailable(error){
 const network=error?.kind==='network',message=error?.message||'正在等待本机工作台返回配置。',main=$('#main');
 main.innerHTML=heading(network?'无法连接本机工作台':'本机服务异常',network?'请检查 WeChatStudio.exe 是否仍在运行。':'程序已经响应，但工作区暂时未能加载。')+`<div class="notice warn" role="alert">${esc(message)}</div><div class="row"><button class="button primary" id="retryStartup">重新加载工作区</button></div><div class="notice">服务恢复后会自动进入${esc(pages.find(p=>p[0]===route)?.[2]||'总览')}。配置尚未加载时无法修改设置；你可以在左侧选择要进入的页面。</div>`;
 $('#retryStartup').onclick=async()=>{const b=$('#retryStartup');b.disabled=true;try{await poll()}finally{if(b.isConnected)b.disabled=false}};
}
