function toast(text,error=false){const n=$('#toast');n.textContent=text;n.style.background=error?'#8b4946':'#193c47';n.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>n.style.display='none',error?10000:4000)}
function modal(title,body){if(dialogCleanup)throw Error('请先完成或关闭当前确认窗口');if(fileBusy)throw Error('文件正在处理，请等待本批次结束');$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=body;if(!$('#dialog').open)$('#dialog').showModal()}
const output=v=>typeof v==='string'?v:JSON.stringify(v,null,2);
