async function render(name,remember=true){
  if(!pages.some(p=>p[0]===name))name='home';
  if(remember)rememberDraft();route=name;const version=++renderVersion;
  $('#crumb').textContent=pages.find(p=>p[0]===name)[2];
  $$('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.page===name);b.setAttribute('aria-current',b.dataset.page===name?'page':'false')});
  if(!state){unavailable(lastPollError);return}
  const mount=document.createElement('div');mount.innerHTML='<div class="empty" role="status">正在加载…</div>';$('#main').replaceChildren(mount);
  try{await views[name](mount);if(version===renderVersion){restoreDraft(name);syncActions()}}
  catch(e){if(version!==renderVersion)return;mount.innerHTML=heading('操作未完成','请检查提示后重试')+`<div class="notice warn">${esc(e.message)}</div><button class="button primary" id="retryView">重试</button>`;$('#retryView').onclick=()=>render(name)}
}
