views.insights=async m=>{m.innerHTML=heading('AI 工具箱','先检查日期与消息，再生成摘要、待办或关键信息。')+`<div class="card section"><div class="grid three"><div class="field"><label>分析会话</label><select id="analysisContact">${choices(contact)}</select></div><div class="field"><label>时间范围（北京时间）</label><select id="analysisRange"><option>最近一周（7天）</option><option>最近一月（30天）</option><option>最近一年（365天）</option><option>自定义日期</option></select></div><div class="field"><label>分析任务</label><select id="analysisTask"><option>对话摘要</option><option>待办提取</option><option>关键信息</option></select></div></div><div class="row" id="dateFields" hidden><div class="field"><label>开始日期</label><input id="dateStart" type="date"></div><div class="field"><label>结束日期（含当天）</label><input id="dateEnd" type="date"></div></div><div class="row">${button('检查范围 / 消息预览','analysisPreview')}${button('开始分析','analyze',true)}</div><div class="notice">最近7/30/365天以当前时刻为基准，无近期消息不回退旧记录；非文本消息不送入文字分析。</div></div><div class="card"><div class="row space"><h2>分析结果</h2>${button('保存文本','saveResult')}</div><div class="result-state" id="analysisOutputStatus">${esc(resultStatus('analysisOutput'))}</div><div id="analysisOutput" class="output">${esc(results.analysisOutput||'选择会话和日期后开始分析。')}</div></div>`;const params=()=>({contact:$('#analysisContact').value,range:$('#analysisRange').value,start:$('#dateStart').value,end:$('#dateEnd').value,task:$('#analysisTask').value});$('#analysisRange').onchange=()=>$('#dateFields').hidden=$('#analysisRange').value!=='自定义日期';bind({analysisPreview:async()=>{const r=await api('/api/analysis',{...params(),preview:true});modal('本次实际使用的消息',`<div class="notice good">${esc(r.description).replace(/\n/g,'<br>')}</div><pre class="output">${esc(r.text||'此范围没有文本消息，不会调用模型。')}</pre>`)},analyze:()=>job('/api/analysis',params(),'analysisOutput'),saveResult:()=>{if(resultStates.analysisOutput!=='success')throw Error('请先完成本次分析');saveText(results.analysisOutput,'聊天分析.txt')}});watchResult('analysisOutput',['#analysisContact','#analysisRange','#analysisTask','#dateStart','#dateEnd']);};
views.statistics=async m=>{m.innerHTML=heading('聊天统计','在本机计算文本消息数量和时间分布，不调用 AI。')+`<div class="row section"><select id="statsContact" style="max-width:400px"><option value="">全部文本会话</option>${choices(contact).replace('<option value="">请选择会话</option>','')}</select>${button('更新统计','stats',true)}</div><div id="statsBody"></div>`;async function load(){const target=$('#statsBody'),selected=$('#statsContact').value;const r=await api('/api/statistics?'+new URLSearchParams({contact:selected}));if(!target.isConnected||$('#statsContact')?.value!==selected)return;const hours=r.hours||{},peak=Math.max(1,...Object.values(hours));target.innerHTML=`<div class="grid metrics">${[['文本消息',r.total],['本人消息',r.own],['身份未知',r.unknown],['日期无效',r.invalid]].map(([t,v])=>`<div class="card metric"><span class="metric-label">${t}</span><div class="metric-value">${fmt(v)}</div></div>`).join('')}</div><div class="card section"><h2>一天中的活跃时段</h2><div class="muted">${esc(r.first||'暂无日期')} 至 ${esc(r.last||'暂无日期')}</div><div class="bar-chart">${Array.from({length:24},(_,h)=>`<div class="bar-column"><div class="bar" style="height:${Math.max(2,Number(hours[h]||0)/peak*135)}px" title="${h}时：${hours[h]||0}条"></div>${h}</div>`).join('')}</div></div><div class="grid two">${[['最活跃日期',r.days],['发送者',r.senders]].map(([t,data])=>`<div class="card"><h2>${t}</h2>${Object.entries(data).sort((a,b)=>b[1]-a[1]).slice(0,10).map(([k,v])=>`<div class="list-line"><span>${esc(k)}</span><b>${fmt(v)} 条</b></div>`).join('')||empty('暂无统计')}</div>`).join('')}</div>`}bind({stats:load});restoreDraft('statistics');await load();};
