 provider.onchange=()=>{key.value='';url.value=({mimo:'https://api.xiaomimimo.com/v1',lmstudio:'http://127.0.0.1:1234/v1',ollama:'http://127.0.0.1:11434/v1'})[provider.value];model.value=provider.value==='mimo'?'mimo-v2.6-pro':'';modelList.innerHTML='';$('#reasoning').value=provider.value==='mimo'?'default':'none';updateAuth()};url.addEventListener('input',updateAuth);
 const controls=['provider','baseUrl','modelId','apiKey','contextSize','maxTokens','reasoning','modelPrompt'].map(id=>document.getElementById(id));
 const transact=async fn=>{if(editing)throw Error('设置正在保存，请稍候');editing=true;for(const el of controls)el.disabled=true;for(const action of ['saveSettings','testModel','listModels','clearKey'])$('[data-action="'+action+'"]').disabled=true;status('正在保存设置或连接服务…');try{return await fn()}catch(e){if(m.isConnected)status(e.message,true);throw e}finally{editing=false;if(m.isConnected){for(const el of controls)el.disabled=false;for(const action of ['saveSettings','testModel','listModels','clearKey'])$('[data-action="'+action+'"]').disabled=false;updateAuth();syncActions()}}};
